    {%- endif %}
    {%- set c_3 -%}
      {%- set c_1 -%}
        {{ ui_text(ui_get(v_stat, ['value'])) }}
      {%- endset -%}
      {{ ui_include('ui/text/text.html.j2', {'p': {'Size': '5xl', 'Weight': 'medium', 'Class': ui_s(ui_cnv(['flex items-center', ui_preset('blocks/presets/defaults.json', ['stats', 'figure'])]))}, 'children': c_1}) }}
      {%- set c_2 -%}
        {{ ui_text(ui_get(v_stat, ['label'])) }}
