    {%- endset -%}
    {{ ui_include('ui/stack/stack.html.j2', {'p': {'Gap': '2', 'Align': ui_s(('center' if ui_t(ui_eq(v_align, 'center')) else 'start'))}, 'children': c_3}) }}
  {%- endset -%}
  {{ ui_include('ui/stack/stack.html.j2', {'p': {'Gap': '6', 'Align': ui_s(('center' if ui_t(ui_eq(v_align, 'center')) else 'start')), 'Class': ui_s(ui_cnv([('text-center' if ui_t(ui_eq(v_align, 'center')) else ''), ui_preset('blocks/presets/defaults.json', ['stats', 'column'])])), 'Attrs': ui_attrs(['data-testid', 'item'])}, 'children': c_4}) }}
